requests.compat._resolve_char_detection:
def _resolve_char_detection():
    """Find supported character detection libraries."""
    chardet = None
    for lib in ('chardet', 'charset_normalizer'):
        if chardet is None:
            try:
                chardet = importlib.import_module(lib)
            except ImportError:
                pass
    return chardet

urllib3.connectionpool._close_pool_conne:
def _close_pool_connections(pool: queue.LifoQueue[typing.Any]) -> None:
    """Drains a queue of connections and closes each one."""
    try:
        while True:
            conn = pool.get(block=False)
            if conn:
                conn.close()
    except queue.Empty:
        pass

urllib3.util.util.reraise:
def reraise(tp: type[BaseException] | None, value: BaseException, tb: TracebackType | None = None) -> typing.NoReturn:
    try:
        if value.__traceback__ is not tb:
            raise value.with_traceback(tb)
        raise value
    finally:
        value = None
        tb = None

requests.status_codes._init:
def _init():
    for (code, titles) in _codes.items():
        for title in titles:
            setattr(codes, title, code)
            if not title.startswith(('\\', '/')):
                setattr(codes, title.upper(), code)

    def doc(code):
        names = ', '.join((f'``{n}``' for n in _codes[code]))
        return '* %d: %s' % (code, names)
    global __doc__
    __doc__ = (__doc__ + '\n' + '\n'.join((doc(code) for code in sorted(_codes))) if __doc__ is not None else None)

requests.adapters._urllib3_request_conte:
def _urllib3_request_context(request: 'PreparedRequest', verify: 'bool | str | None', client_cert: 'typing.Tuple[str, str] | str | None', poolmanager: 'PoolManager') -> '(typing.Dict[str, typing.Any], typing.Dict[str, typing.Any])':
    host_params = {}
    pool_kwargs = {}
    parsed_request_url = urlparse(request.url)
    scheme = parsed_request_url.scheme.lower()
    port = parsed_request_url.port
    cert_reqs = 'CERT_REQUIRED'
    if verify is False:
        cert_reqs = 'CERT_NONE'
    elif isinstance(verify, str):
        if not os.path.isdir(verify):
            pool_kwargs['ca_certs'] = verify
        else:
            pool_kwargs['ca_cert_dir'] = verify
    pool_kwargs['cert_reqs'] = cert_reqs
    if client_cert is not None:
        if (isinstance(client_cert, tuple) and len(client_cert) == 2):
            pool_kwargs['cert_file'] = client_cert[0]
            pool_kwargs['key_file'] = client_cert[1]
        else:
            pool_kwargs['cert_file'] = client_cert
    host_params = {'scheme': scheme, 'host': parsed_request_url.hostname, 'port': port}
    return (host_params, pool_kwargs)

urllib3.util.connection._has_ipv6:
def _has_ipv6(host: str) -> bool:
    """Returns True if the system can bind an IPv6 address."""
    sock = None
    has_ipv6 = False
    if socket.has_ipv6:
        try:
            sock = socket.socket(socket.AF_INET6)
            sock.bind((host, 0))
            has_ipv6 = True
        except Exception:
            pass
    if sock:
        sock.close()
    return has_ipv6

requests.utils.parse_header_links:
def parse_header_links(value):
    """Return a list of parsed link headers proxies.

    i.e. Link: <http:/.../front.jpeg>; rel=front; type="image/jpeg",<http://.../back.jpeg>; rel=back;type="image/jpeg"

    :rtype: list
    """
    links = []
    replace_chars = ' \'"'
    value = value.strip(replace_chars)
    if not value:
        return links
    for val in re.split(', *<', value):
        try:
            (url, params) = val.split(';', 1)
        except ValueError:
            (url, params) = (val, '')
        link = {'url': url.strip('<> \'"')}
        for param in params.split(';'):
            try:
                (key, value) = param.split('=')
            except ValueError:
                break
            link[key.strip(replace_chars)] = value.strip(replace_chars)
        links.append(link)
    return links
